#include "naval_repair_exact_detail.hpp"
#include "hanmo/resident_world_api.hpp"
#include <algorithm>
namespace hanmo::resident {using namespace naval_repair_exact_detail;namespace {
void registration(const ActionTimeRegistration& r){if(r.action_kind!="naval_repair"||r.owner_domain!="military_naval"||r.profile_id!="military_action_time"||r.profile_version!=1||r.source_schema!=2||r.mode!=ActionTimeMode::fixed_duration||r.remaining_meaning!=ActionRemainingMeaning::service_estimate||r.shared_gate_kind||!r.retained_wait_phases.empty())fail("ExactNavalRepairRegistrationMismatch");}
void same_proof(const ActionTimeOwnerProof& a,const ActionTimeOwnerProof& b){if(a.action_ref!=b.action_ref||a.action_kind!=b.action_kind||a.actor_id!=b.actor_id||a.participant_actor_ids!=b.participant_actor_ids||a.phase!=b.phase||a.source_schema!=b.source_schema||!same_source(a.original_execution_source,b.original_execution_source)||a.terminal_result_ref!=b.terminal_result_ref)fail("StaleExactNavalRepairOwnerProof",a.action_ref);}
}
ActionTimeRegistration exact_naval_repair_action_registration(){return {"naval_repair","military_naval","military_action_time",1,2,ActionTimeMode::fixed_duration,ActionRemainingMeaning::service_estimate,{},{}};}
Status NativeNavalRepairActionTimeRead::enumerate_action_time_owners(const ActionTimeRegistration& r,ActionTimeOwnerIdSink& output)const{return status([&]{registration(r);bound(common_,military_,naval_,state_,context_);for(const auto& row:state_.naval_repair_time_sources.rows()){take(read_action_time_owner(r,row.first));take(output.append(row.first));}});}
Outcome<ActionTimeOwnerProof> NativeNavalRepairActionTimeRead::read_action_time_owner(const ActionTimeRegistration& r,const StableId& id)const{return guard<ActionTimeOwnerProof>([&]{registration(r);const auto& f=fact(state_,id);validate_shape(common_,military_,naval_,state_,context_,f);const auto& original_members=f.original_terms.participants;CheckpointVector<std::string_view> members,empty;members.reserve(original_members.size());for(const auto& member:original_members)members.push_back(member);const auto original_source=SourceRefBuildView{f.timing.start_fact_ref.domain,f.timing.start_fact_ref.kind,f.timing.start_fact_ref.id};
 ActionTimeOwnerProofBuildView proof{id,"naval_repair",f.original_terms.actor_id,{members},original_source,2,MomentOwnerSourceBuildView{original_source,2},ActionTimeOwnerPhase::working,{},{},{},{empty},{}};
 if(f.original_result){proof.phase=ActionTimeOwnerPhase::terminal;proof.ended_source=MomentOwnerSourceBuildView{{f.timing.result_ref->domain,f.timing.result_ref->kind,f.timing.result_ref->id},2};proof.terminal_result_ref=f.original_result->id;}
 else{const auto* a=common_.action(id);if(!a||a->kind!="naval_repair"||a->actor_id!=f.original_terms.actor_id||!std::equal(a->participants.begin(),a->participants.end(),members.begin(),members.end())||a->start_tick!=f.timing.started_at.half_day_tick)fail("ExactNavalRepairActualActionRequired",id);proof.phase=ActionTimeOwnerPhase::working;}return ActionTimeOwnerProof(proof);
});}
Outcome<WorldMoment> NativeNavalRepairActionTimeRead::read_action_time_source(const ElapsedTimeSource& source)const{return guard<WorldMoment>([&]{const auto* original=std::get_if<MomentOwnerSource>(&source);if(!original||original->source_schema!=2||original->source_ref.domain!="military_naval")fail("ExactNavalRepairMomentSourceRequired");const auto& ref=original->source_ref;if(ref.kind=="naval_repair_start"){const auto& f=fact(state_,ref.id);validate_shape(common_,military_,naval_,state_,context_,f);return f.timing.started_at;}if(ref.kind=="naval_repair_result"){const auto& f=result_fact(state_,ref.id);validate_shape(common_,military_,naval_,state_,context_,f);return *f.timing.completion_or_interruption_at;}fail("ExactNavalRepairMomentSourceRequired",ref.id);});}
Status NativeNavalRepairActionTimeRead::validate_fixed_action_sources(const ActionTimeRegistration& r,const ActionTimeOwnerProof& supplied,const ActionElapsedState& e,const std::vector<FixedServiceTransition>& transitions)const{return status([&]{registration(r);same_proof(take(read_action_time_owner(r,e.action_ref)),supplied);const auto& f=fact(state_,e.action_ref);take(validate_fact_history(common_,military_,naval_,state_,context_,f,e,true));const auto& t=f.timing;if(transitions.size()!=(f.original_result?2u:1u))fail("ExactNavalRepairFixedHistoryMismatch",t.action_ref);
 for(std::size_t i=0;i<transitions.size();++i){const auto& row=transitions[i];if(row.source_schema!=1||row.action_ref!=t.action_ref||row.transition_ordinal!=Integer(i)||row.execution_source_schema!=2||!same_source(row.execution_source_ref,t.start_fact_ref))fail("ExactNavalRepairFixedSourceMismatch",t.action_ref);
  if(!i){const auto* cause=std::get_if<FixedOwnerAdopted>(&row.cause);if(row.kind!=FixedTransitionKind::started||row.previous_transition_ref||!row.previous_input_basis_refs.empty()||!cause||cause->owner_source_schema!=2||!same_source(cause->owner_source_ref,t.start_fact_ref)||!same_moment(row.occurred_at,t.started_at,context_.budget)||compare(row.credited_at.value,integer(0,context_.budget),context_.budget)||row.input_basis_refs.size()!=1||row.terminal_disposition)fail("ExactNavalRepairStartedHistoryMismatch",t.action_ref);const auto* input=std::get_if<FixedAppliedInput>(&row.input_basis_refs.front());if(!input||input->source_schema!=2||!same_source(input->source_ref,t.start_fact_ref))fail("ExactNavalRepairAdoptedInputRequired",t.action_ref);}
  else{const auto* cause=std::get_if<FixedOwnerTerminated>(&row.cause);if(row.kind!=FixedTransitionKind::terminal||!cause||cause->owner_result_schema!=2||!same_source(cause->owner_result_ref,*t.result_ref)||row.previous_transition_ref!=std::optional<StableId>{transitions.front().transition_id}||!same_moment(row.occurred_at,*t.completion_or_interruption_at,context_.budget)||compare(row.credited_at.value,e.credited_units.value,context_.budget)||!row.input_basis_refs.empty()||row.previous_input_basis_refs.size()!=transitions.front().input_basis_refs.size()||row.terminal_disposition!=std::optional<FixedTerminalDisposition>{disposition(*f.original_result)})fail("ExactNavalRepairTerminalHistoryMismatch",t.action_ref);for(std::size_t k=0;k<row.previous_input_basis_refs.size();++k)if(!same_fixed_input_ref(row.previous_input_basis_refs[k],transitions.front().input_basis_refs[k]))fail("ExactNavalRepairTerminalInputMismatch",t.action_ref);}
 }
});}
Status NativeNavalRepairActionTimeRead::validate_shared_action_sources(const ActionTimeRegistration&,const ActionTimeOwnerProof&,const SharedWorkElapsedState&)const{return common_failure("ExactNavalRepairDoesNotOwnSharedWork");}
Outcome<RunStop> NativeNavalRepairActionTimeRead::read_action_continuation_stop(const ActionTimeRegistration& r,const ActionTimeOwnerProof& supplied,const WorldMoment& now)const{return guard<RunStop>([&]{const auto proof=take(read_action_time_owner(r,supplied.action_ref));same_proof(proof,supplied);const auto& f=fact(state_,proof.action_ref);if(f.original_result)return f.original_result->success?RunStop::completed:RunStop::blocked;const auto* e=find_fixed_elapsed(elapsed_,proof.action_ref);if(!e||take(compare_world_moments(e->last_settled_at,now,context_.budget))>0)fail("ExactNavalRepairElapsedRequired",proof.action_ref);return RunStop::budget_exhausted;});}
Outcome<OriginalActionRemaining> NativeNavalRepairActionTimeRead::read_original_action_remaining(const ActionTimeRegistration& r,const ActionTimeOwnerProof& supplied,const WorldMoment&)const{return guard<OriginalActionRemaining>([&]()->OriginalActionRemaining{const auto proof=take(read_action_time_owner(r,supplied.action_ref));same_proof(proof,supplied);const auto* e=find_fixed_elapsed(elapsed_,proof.action_ref);if(!e)fail("ExactNavalRepairElapsedRequired",proof.action_ref);return ActualServiceRemaining{ActualServiceRemainingBuildView{proof.phase==ActionTimeOwnerPhase::terminal?HalfDayDuration{}:take(scale_units_to_duration(take(subtract_work_units(e->required_units,e->credited_units,context_.budget)),context_.scale.units_per_half_day,context_.budget)),{proof.original_execution_source.domain,proof.original_execution_source.kind,proof.original_execution_source.id},2}};});}
Outcome<StableId> NativeNavalRepairActionTimeRead::read_gate_result_id(const SharedWorkGateResult&)const{return {false,{},common_failure("ExactNavalRepairDoesNotOwnSharedWork").error};}
Outcome<SharedWorkGateResult> NativeNavalRepairActionTimeRead::read_original_gate_result(const StableId&)const{return {false,{},common_failure("ExactNavalRepairDoesNotOwnSharedWork").error};}
Status NativeNavalRepairActionTimeRead::validate_original_gate_result(const SharedWorkGateResult&)const{return common_failure("ExactNavalRepairDoesNotOwnSharedWork");}
}
